/**
 * =============================================================================
 * APP FACTORY — DEMO SERVICE
 * =============================================================================
 * Builds the express app. Split out of index.ts (KS-641) so the real
 * middleware wiring — including the inbound auth guard — can be exercised in
 * tests. index.ts previously called app.listen() at module load, so importing
 * it started a listener; nothing could assert that the guard was actually
 * MOUNTED, only that it existed.
 * =============================================================================
 */

import express, { Request, Response } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import morgan from 'morgan';
import { rejectNulBytes } from '@secuura/shared';

import { createLogger } from './utils/logger';
import { requireDemoKey } from './middleware/demoGuard';
import { healthRouter } from './routes/health';
import { personaRouter } from './routes/persona';
import { stateRouter } from './routes/state';
import { resetRouter } from './routes/reset';
import { scenarioRouter } from './routes/scenario';

const logger = createLogger('demo-service');

export function createApp() {
  const app = express();

  // ===========================================================================
  // MIDDLEWARE
  // ===========================================================================

  app.use(helmet());
  app.use(cors({
    origin: process.env.CORS_ORIGINS?.split(',') || [
      'http://localhost:6882',
      'http://localhost:6881',
    ],
    credentials: true,
  }));
  app.use(cookieParser());
  app.use(express.json());
  // KS-800: the control-byte guard inspects `req.body`, so it MUST be mounted
  // after every body parser — a guard above the parser walks an empty object and
  // passes everything. demo-service mounted a parser and no guard at all, which
  // the KS-781 class test could not see: its scan returns null for a file with no
  // guard, so an unguarded service was invisible rather than failing. That hole is
  // closed by LEG E in ks781-p3-3-body-parser-order.test.ts.
  app.use(rejectNulBytes());
  app.use(morgan('combined', {
    stream: { write: (message: string) => logger.info(message.trim()) },
  }));

  // ===========================================================================
  // ROUTES
  // ===========================================================================

  // /health stays PUBLIC and must be mounted before the guard: the compose
  // healthcheck calls it unauthenticated
  // (`wget --spider http://localhost:4030/demo-api/health`), so guarding it
  // would fail the container rather than secure it.
  app.use('/demo-api', healthRouter);

  // KS-641: everything below this line requires the shared demo key. It sits
  // between the routers rather than inside them so that adding a new /demo-api
  // router inherits the guard by default instead of opting into it.
  app.use('/demo-api', requireDemoKey);

  app.use('/demo-api', personaRouter);
  app.use('/demo-api', stateRouter);
  app.use('/demo-api', resetRouter);
  app.use('/demo-api', scenarioRouter);

  // 404 handler
  app.use((_req: Request, res: Response) => {
    res.status(404).json({
      success: false,
      error: { code: 'NOT_FOUND', message: `Cannot ${_req.method} ${_req.path}` },
    });
  });

  return app;
}

// Mocks MUST precede imports of modules under test
vi.mock('../utils/logger', () => ({
  logger: { debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn() },
  createLogger: () => ({ debug: vi.fn(), info: vi.fn(), warn: vi.fn(), error: vi.fn() }),
}));

vi.mock('../services/authClient', () => ({
  authenticatePersona: vi.fn(),
}));

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { createApp } from '../app';
import { MIN_DEMO_KEY_LENGTH } from '../middleware/demoGuard';
import { assertDemoServiceEnabled } from '../middleware/demoGuard';
import { authenticatePersona } from '../services/authClient';

// =============================================================================
// HELPERS
// =============================================================================

const KEY = 'test-demo-key-0123456789abcdef';

async function startServer(app: ReturnType<typeof createApp>): Promise<{ url: string; close: () => void }> {
  return new Promise((resolve_) => {
    const server = app.listen(0, '127.0.0.1', () => {
      const addr = server.address();
      const port = typeof addr === 'object' && addr ? addr.port : 0;
      resolve_({ url: `http://127.0.0.1:${port}`, close: () => server.close() });
    });
  });
}

const mockAuthenticatePersona = vi.mocked(authenticatePersona);

const ORIGINAL_ENV = { ...process.env };

beforeEach(() => {
  vi.clearAllMocks();
  process.env.NODE_ENV = 'development';
  process.env.DEMO_SERVICE_ENABLED = 'true';
  process.env.DEMO_SERVICE_KEY = KEY;
});

afterEach(() => {
  process.env = { ...ORIGINAL_ENV };
});

// =============================================================================
// KS-641 — INBOUND AUTH ON demo-service
// =============================================================================
//
// The acceptance criterion this file exists to satisfy: the refusal must be
// proved with the route REACHABLE, not proved by one of the three incidental
// barriers (unrouted gateway / unpublished port / unseeded personas) that
// happen to hold it shut today. Mounting the real app in-process lifts all
// three, so every assertion below hits the handler's own guard.

describe('KS-641: demo-service inbound auth', () => {
  describe('POST /demo-api/persona/switch — the admin-token mint', () => {
    it('refuses an UNAUTHENTICATED caller with 401 and mints no token', async () => {
      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/persona/switch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ persona: 'admin' }),
        });

        expect(response.status).toBe(401);

        const body = await response.json();
        expect(body.success).toBe(false);
        expect(body.error.code).toBe('UNAUTHORIZED');

        // The point of the ticket: no Platform Admin token, no refresh cookie.
        expect(body.data).toBeUndefined();
        expect(response.headers.get('set-cookie')).toBeNull();

        // The guard must short-circuit BEFORE the auth service is called —
        // otherwise an anonymous caller still drives credentialed traffic.
        expect(mockAuthenticatePersona).not.toHaveBeenCalled();
      } finally {
        close();
      }
    });

    it('refuses a WRONG key with 403 and mints no token', async () => {
      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/persona/switch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Demo-Key': 'not-the-key' },
          body: JSON.stringify({ persona: 'admin' }),
        });

        expect(response.status).toBe(403);

        const body = await response.json();
        expect(body.error.code).toBe('FORBIDDEN');
        expect(mockAuthenticatePersona).not.toHaveBeenCalled();
      } finally {
        close();
      }
    });

    // POSITIVE CONTROL — required by the ticket. Without this the suite would
    // pass just as well against a blanket refusal, which is not a guard.
    it('POSITIVE CONTROL: an authorised caller still switches persona', async () => {
      mockAuthenticatePersona.mockResolvedValue({
        success: true,
        accessToken: 'jwt-token-admin',
        user: { id: 'user-admin', email: 'admin@secuura.io' },
        setCookieHeader: 'refresh_token=rt_admin; Path=/api/auth; HttpOnly',
      });

      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/persona/switch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Demo-Key': KEY },
          body: JSON.stringify({ persona: 'admin' }),
        });

        expect(response.status).toBe(200);

        const body = await response.json();
        expect(body.success).toBe(true);
        expect(body.data.accessToken).toBe('jwt-token-admin');
        expect(response.headers.get('set-cookie')).toContain('refresh_token');
        expect(mockAuthenticatePersona).toHaveBeenCalledOnce();
      } finally {
        close();
      }
    });
  });

  describe('the other mutating routes are guarded too', () => {
    // /reset is pg_restore + Redis FLUSHALL behind nothing but an
    // X-Demo-Reset header, which is an accidental-trigger guard rather than
    // an access control. It is the second unauthenticated verb on this
    // service and is arguably worse than the token mint.
    it('POST /demo-api/reset refuses an unauthenticated caller (X-Demo-Reset is not auth)', async () => {
      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/reset`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Demo-Reset': 'true' },
        });

        expect(response.status).toBe(401);
      } finally {
        close();
      }
    });

    it('POST /demo-api/presenter-mode refuses an unauthenticated caller', async () => {
      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/presenter-mode`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ enabled: true }),
        });

        expect(response.status).toBe(401);
      } finally {
        close();
      }
    });
  });

  describe('GET /demo-api/health stays public', () => {
    // The compose healthcheck calls this unauthenticated
    // (docker-compose.yml: wget --spider http://localhost:4030/demo-api/health),
    // so guarding it would fail the container rather than secure it.
    it('answers 200 without a key', async () => {
      const { url, close } = await startServer(createApp());

      try {
        const response = await fetch(`${url}/demo-api/health`);
        expect(response.status).toBe(200);
        expect(await response.json()).toEqual({ status: 'ok', service: 'demo-service' });
      } finally {
        close();
      }
    });
  });
});

// =============================================================================
// KS-641 — NON-PROD GATE (fail closed)
// =============================================================================

describe('KS-641: demo-service refuses to run where it does not belong', () => {
  it('refuses to start when NODE_ENV=production, even if explicitly enabled', () => {
    process.env.NODE_ENV = 'production';
    process.env.DEMO_SERVICE_ENABLED = 'true';

    expect(() => assertDemoServiceEnabled()).toThrow(/production/i);
  });

  it('refuses to start unless DEMO_SERVICE_ENABLED is an explicit opt-in', () => {
    delete process.env.DEMO_SERVICE_ENABLED;

    expect(() => assertDemoServiceEnabled()).toThrow(/DEMO_SERVICE_ENABLED/);
  });

  it('refuses to start when DEMO_SERVICE_KEY is unset — no key means no guard', () => {
    delete process.env.DEMO_SERVICE_KEY;

    expect(() => assertDemoServiceEnabled()).toThrow(/DEMO_SERVICE_KEY/);
  });

  it('refuses a trivially guessable DEMO_SERVICE_KEY', () => {
    process.env.DEMO_SERVICE_KEY = 'demo';

    expect(() => assertDemoServiceEnabled()).toThrow(/DEMO_SERVICE_KEY/);
  });

  it('refuses to start when NODE_ENV is UNSET (#737 review — fail closed, not fail dev)', () => {
    // Was: `process.env.NODE_ENV ?? 'development'`, so an environment that had
    // not declared itself sailed past the "never production" branch. A service
    // that mints Platform Admin tokens does not get the benefit of the doubt.
    delete process.env.NODE_ENV;

    expect(() => assertDemoServiceEnabled()).toThrow(/NODE_ENV is not set/i);
  });

  it('refuses a long-but-degenerate DEMO_SERVICE_KEY (#737 review — length is not entropy)', () => {
    // 16 chars clears MIN_DEMO_KEY_LENGTH; one distinct character is not a secret.
    process.env.DEMO_SERVICE_KEY = 'aaaaaaaaaaaaaaaa';
    expect(process.env.DEMO_SERVICE_KEY.length).toBeGreaterThanOrEqual(MIN_DEMO_KEY_LENGTH);

    expect(() => assertDemoServiceEnabled()).toThrow(/distinct characters/i);
  });

  it('POSITIVE CONTROL: a correctly configured non-prod deployment starts', () => {
    expect(() => assertDemoServiceEnabled()).not.toThrow();
  });
});

// =============================================================================
// KS-641 — THE CARRIED HONESTY DEFECT
// =============================================================================
//
// nginx-demo.conf's /health advertises a hardcoded route map with no
// relationship to the `location` blocks it describes, so it cannot be kept in
// step by construction. Asserting the relationship is what stops it drifting
// again. The local sibling nginx.conf is the positive control: it carries the
// same literal map WITHOUT the /demo-api/ entry, so one of the two was
// maintained and the other was not.

describe('KS-641: the gateway /health route map must not advertise what it does not serve', () => {
  const CONF_DIR = resolve(__dirname, '../../../../docker/nginx-gateway');

  function readConf(name: string): string {
    return readFileSync(resolve(CONF_DIR, name), 'utf8');
  }

  /** Route keys the `/health` literal claims, e.g. "/api/", "/demo-api/". */
  function advertisedRoutes(conf: string): string[] {
    const health = conf.match(/location = \/health \{[\s\S]*?\n\s{4}\}/);
    if (!health) throw new Error('no `location = /health` block found — the test cannot match');
    const routes = health[0].match(/"routes":\{(.*?)\}/);
    if (!routes) throw new Error('no "routes" map found inside the /health block');
    return [...routes[1].matchAll(/"(\/[^"]*)":"/g)].map((m) => m[1]);
  }

  /** Path prefixes the conf actually serves via a `location` block. */
  function servedPrefixes(conf: string): string[] {
    return [...conf.matchAll(/^\s*location\s+(?:\^~\s+)?(\/[^\s{]*)\s*\{/gm)].map((m) => m[1]);
  }

  // #737 review — DIRECTION MATTERS, and this asserts only ONE of the two.
  // `advertised ⊆ served` catches the OVER-claim (the /health map naming a route
  // nginx does not serve), which is the defect KS-641 was filed about. It does NOT
  // catch the UNDER-claim: today both confs serve six prefixes the map never
  // mentions — /system/, /webhooks/, /originate/, /analytics/, /showcase/, /pricing/
  // — two of which (/originate/, /analytics/) bypass the API gateway entirely.
  // Fixing those six is out of scope here; the test below PINS the set so the
  // acceptance criterion cannot be read as fully met, and so the number cannot
  // drift unnoticed in either direction.
  it.each(['nginx-demo.conf', 'nginx.conf'])(
    '%s advertises no route it does not serve (OVER-claim direction only)',
    (file) => {
      const conf = readConf(file);
      const advertised = advertisedRoutes(conf);
      const served = servedPrefixes(conf);

      // Guard the guard: if the parser silently matched nothing, a conf that
      // advertises everything would still pass. Both halves must be non-empty.
      expect(advertised.length).toBeGreaterThan(0);
      expect(served.length).toBeGreaterThan(0);

      const unserved = advertised.filter(
        (route) => route !== '/' && !served.some((prefix) => prefix.startsWith(route)),
      );

      expect(unserved).toEqual([]);
    },
  );

  it('specifically: nginx-demo.conf does not advertise /demo-api/', () => {
    expect(advertisedRoutes(readConf('nginx-demo.conf'))).not.toContain('/demo-api/');
  });

  it('POSITIVE CONTROL: both confs still advertise /api/, which they do serve', () => {
    for (const file of ['nginx-demo.conf', 'nginx.conf']) {
      expect(advertisedRoutes(readConf(file))).toContain('/api/');
    }
  });

  it('pins the UNDER-claim set — served but never advertised (#737 review)', () => {
    // The converse of the assertion above. Not a failure: fixing these is KS-491's,
    // not this PR's. Pinning them means the acceptance criterion "the map matches
    // the served location blocks" is visibly PARTIALLY met rather than silently
    // read as done, and a seventh appearing trips this rather than going unnoticed.
    const KNOWN_UNADVERTISED = [
      '/analytics/',
      '/originate/',
      '/pricing/',
      '/showcase/',
      '/system/',
      '/webhooks/',
    ];

    for (const file of ['nginx-demo.conf', 'nginx.conf']) {
      const conf = readConf(file);
      const advertised = advertisedRoutes(conf);
      const served = servedPrefixes(conf);

      // Guard the guard, same as above — a parser matching nothing must not pass.
      expect(advertised.length).toBeGreaterThan(0);
      expect(served.length).toBeGreaterThan(0);

      const unadvertised = served
        .filter((prefix) => prefix.endsWith('/') && prefix !== '/')
        .filter((prefix) => !advertised.includes(prefix))
        .sort();

      expect(unadvertised, `${file}: the served-but-unadvertised set changed`).toEqual(
        KNOWN_UNADVERTISED,
      );
    }
  });
});
